#!/usr/bin/env python3
import json, os, pathlib, sys

def main() -> int:
    payload = json.loads(sys.stdin.read() or "{}")
    cid = payload.get("conversationId", "default")
    data_dir = pathlib.Path(os.environ.get("PLUGIN_DATA", "/tmp/cf-data"))
    fb_path = data_dir / "feedback" / f"{cid}.json"

    if not fb_path.exists():
        print(json.dumps({}))
        return 0

    diagnostics = json.loads(fb_path.read_text(encoding="utf-8"))
    fb_path.unlink(missing_ok=True)

    summary = "\n".join(diagnostics.get("errors", [])[:10])
    print(json.dumps({
        "injectSteps": [{
            "systemMessage": f"[Code Factory Post-Edit Gate] Fix these lint/type issues immediately:\n{summary}"
        }]
    }))
    return 0

if __name__ == "__main__":
    raise SystemExit(main())

